#!/usr/bin/env node
// Renders index.html (fully static; works without JavaScript) from:
//   _data/site.json          page content (null values render as visible TODO boxes)
//   _data/publications.json  generated by scripts/sync.mjs — never edit by hand
//   _data/overrides.json     manual publication facts (co-first, notes, code/data links)
//   _data/talks.json         talks and posters
//   _data/images.json        generated by scripts/images.mjs (dimensions + formats)
// Also writes sitemap.xml. Run: npm run render

import { readFile, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const read = async (f, fallback) => {
  try { return JSON.parse(await readFile(path.join(ROOT, f), "utf8")); }
  catch (e) { if (fallback !== undefined && e.code === "ENOENT") return fallback; throw e; }
};

const site = await read("_data/site.json");
const pubs = await read("_data/publications.json", []);
const overrides = await read("_data/overrides.json");
const talks = await read("_data/talks.json", []);
const images = await read("_data/images.json", {});

// ---------- helpers ----------
const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const todo = (what) => `<span class="todo">TODO: ${esc(what)}</span>`;
const todoBlock = (what, cls = "") => `<div class="todo todo-block ${cls}">TODO: ${esc(what)}</div>`;
const ext = (href, text, cls = "") => `<a href="${esc(href)}"${cls ? ` class="${cls}"` : ""}>${esc(text)}</a>`;

function initials(given) {
  return (given || "").split(/[\s.\-]+/).filter(Boolean).map((p) => p[0].toUpperCase()).join("");
}
function familyName(f) {
  return f === f.toUpperCase() && f.length > 2 ? f.charAt(0) + f.slice(1).toLowerCase() : f;
}
const isSelf = (a) => a.family.toLowerCase() === "bauer" && (a.given || "").trim().toLowerCase().startsWith("s");
const authorLabel = (a) => `${familyName(a.family)} ${initials(a.given)}`.trim();

function picture(name, alt, { eager = false, cls = "", sizes = "100vw" } = {}) {
  const img = images[name];
  if (!img) return null;
  const src = (f) => `assets/img/${name}.${f}`;
  const sources = img.formats.filter((f) => f !== img.fallback).map((f) => `<source type="image/${f}" srcset="${src(f)}">`).join("");
  const loading = eager ? `fetchpriority="high" decoding="async"` : `loading="lazy" decoding="async"`;
  return `<picture class="${cls}">${sources}<img src="${src(img.fallback)}" alt="${esc(alt)}" width="${img.width}" height="${img.height}" sizes="${sizes}" ${loading}></picture>`;
}

// ---------- decorative trace (static SVG, generated once at build) ----------
function traceSvg() {
  const W = 1200, H = 84, mid = 34, cyc = 22, bout = 400;
  const env = (x) => 0.12 + 0.88 * Math.sin((Math.PI * x) / bout) ** 4;
  let d = "";
  for (let x = 0; x <= W; x += 2) d += `${x ? "L" : "M"}${x} ${(mid - 26 * env(x) * Math.sin((2 * Math.PI * x) / cyc)).toFixed(1)}`;
  let t = "";
  for (let c = cyc / 4; c <= W; c += cyc) if (env(c) > 0.55) t += `M${c.toFixed(1)} ${H - 14}V${H - 2}`;
  return `<svg class="trace" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false"><path class="wave" vector-effect="non-scaling-stroke" d="${d}"/><path class="spk" vector-effect="non-scaling-stroke" d="${t}"/></svg>`;
}

// ---------- publications ----------
function role(p, o) {
  if (o.role) return o.role;
  return p.authors[0] && isSelf(p.authors[0]) ? "first" : null;
}

function citation(p) {
  const bits = [];
  if (p.volume) bits.push(p.volume + (p.issue ? `(${p.issue})` : ""));
  if (p.pages) bits.push(p.pages);
  return bits.join(":");
}

function pubItem(p) {
  const o = overrides.entries?.[p.doi] || {};
  const r = role(p, o);
  const authors = p.authors.map((a) => (isSelf(a) ? `<strong>${esc(authorLabel(a))}</strong>` : esc(authorLabel(a)))).join(", ");
  const badges = [
    r === "first" && `<span class="badge badge-lead">First author</span>`,
    r === "co-first" && `<span class="badge badge-lead">Co-first author</span>`,
    p.type === "preprint" && `<span class="badge badge-pre">Preprint</span>`,
    o.note && `<span class="badge badge-note">${esc(o.note)}</span>`,
  ].filter(Boolean).join("");
  const links = [
    o.summary && ext(o.summary, "Interactive summary", "primary"),
    ext(`https://doi.org/${p.doi}`, "DOI"),
    o.pdf && ext(o.pdf, "PDF"),
    p.pmcid && ext(`https://pmc.ncbi.nlm.nih.gov/articles/${p.pmcid}/`, "Free full text"),
    p.pmid && ext(`https://pubmed.ncbi.nlm.nih.gov/${p.pmid}/`, "PubMed"),
    ...p.preprints.map((d, i, a) => ext(`https://doi.org/${d}`, a.length > 1 ? `Preprint ${i + 1}` : "Preprint")),
    o.code && ext(o.code, "Code"),
    o.data && ext(o.data, "Data"),
    o.slides && ext(o.slides, "Slides"),
  ].filter(Boolean).join("");
  const bib = p.bibtex
    ? `<details class="bib"><summary>BibTeX</summary><div class="bib-body"><pre><code>${esc(p.bibtex)}</code></pre><button type="button" class="copy" hidden>Copy BibTeX</button></div></details>`
    : "";
  const cite = citation(p);
  return `<article class="pub" id="doi-${esc(p.doi.replace(/[^a-z0-9]+/gi, "-"))}" data-role="${r || ""}" data-type="${p.type}">
  <h4><a href="https://doi.org/${esc(p.doi)}">${esc(p.title)}</a></h4>
  <p class="authors">${authors}</p>
  <p class="venue"><span class="journal">${esc(p.journal)}</span>${cite ? ` ${esc(cite)}` : ""}${p.type === "preprint" && p.date ? ` · ${esc(p.date.slice(0, 4))}` : ""}</p>
  <div class="row">${badges ? `<div class="badges">${badges}</div>` : ""}<div class="pub-links">${links}</div></div>
  ${bib}
</article>`;
}

function publicationsHtml() {
  if (!pubs.length) return todoBlock("publication list is empty: run the sync workflow (Actions → Sync publications)");
  const groups = [];
  const pre = pubs.filter((p) => p.type === "preprint");
  if (pre.length) groups.push(["Preprints", pre]);
  const years = [...new Set(pubs.filter((p) => p.type !== "preprint").map((p) => p.year))].sort((a, b) => b - a);
  for (const y of years) groups.push([String(y), pubs.filter((p) => p.type !== "preprint" && p.year === y)]);
  return groups.map(([label, list]) => `<section class="group" aria-labelledby="g-${esc(label)}">
<h3 class="group-label" id="g-${esc(label)}"><span>${esc(label)}</span></h3>
<div class="items">
${list.map(pubItem).join("\n")}
</div>
</section>`).join("\n");
}

// ---------- other sections ----------
function researchHtml() {
  return site.research.map((t, i) => {
    const fig = t.figure ? picture(t.figure, t.figureAlt || "", { sizes: "(min-width: 900px) 360px, 100vw" }) : null;
    return `<article class="theme">
  <div class="theme-fig">${fig ? `<figure>${fig}${t.figureCredit ? `<figcaption>${esc(t.figureCredit)}</figcaption>` : ""}</figure>` : todoBlock(`figure for theme ${i + 1} (with alt text and licence/credit)`, "fig-ph")}</div>
  <div class="theme-text">
    <h3>${t.title ? esc(t.title) : todo(`theme ${i + 1} title`)}</h3>
    <p>${t.text ? esc(t.text) : todo(`theme ${i + 1}: 2–3 sentences in your own words`)}</p>
  </div>
</article>`;
  }).join("\n");
}

function talksHtml() {
  if (!talks.length) return todoBlock("add talks and posters to _data/talks.json (date YYYY-MM, type talk|poster, title, event, location, optional url)");
  return `<ol class="talks">${talks.slice().sort((a, b) => b.date.localeCompare(a.date)).map((t) => `<li>
  <span class="talk-date">${esc(t.date)}</span>
  <div><span class="badge ${t.type === "poster" ? "badge-note" : "badge-lead"}">${t.type === "poster" ? "Poster" : "Talk"}</span>
  <p class="talk-title">${t.url ? ext(t.url, t.title) : esc(t.title)}</p>
  <p class="talk-meta">${esc([t.event, t.location].filter(Boolean).join(" · "))}</p></div>
</li>`).join("")}</ol>`;
}

// CSS is inlined (single-page site): saves a render-blocking request on slow connections.
const css = (await readFile(path.join(ROOT, "assets", "style.css"), "utf8"))
  .replace(/url\("fonts\//g, 'url("assets/fonts/')
  .replace(/\/\*[\s\S]*?\*\//g, "").replace(/\n\s*/g, "\n").trim();
const hasCv = site.cv && existsSync(path.join(ROOT, site.cv));
const emailHtml = site.email ? `<a href="mailto:${esc(site.email)}">${esc(site.email)}</a>` : todo("public email address");

// ---------- JSON-LD ----------
function jsonLd() {
  const person = {
    "@type": "Person", "@id": site.url + "#person", name: site.name, url: site.url,
    jobTitle: "PhD candidate in Neuroscience",
    affiliation: { "@type": "CollegeOrUniversity", name: "Erasmus MC", url: "https://www.erasmusmc.nl/" },
    sameAs: site.links.map((l) => l.url).filter((u) => !u.includes("pubmed")),
    ...(site.email ? { email: "mailto:" + site.email } : {}),
    ...(site.photo && images[site.photo] ? { image: site.url + `assets/img/${site.photo}.${images[site.photo].fallback}` } : {}),
  };
  const articles = pubs.map((p) => ({
    "@type": "ScholarlyArticle",
    headline: p.title.length > 110 ? p.title.slice(0, 107) + "…" : p.title,
    name: p.title,
    author: p.authors.map((a) => (isSelf(a) ? { "@id": site.url + "#person" } : { "@type": "Person", name: `${a.given} ${familyName(a.family)}`.trim() })),
    datePublished: p.date,
    isPartOf: { "@type": p.type === "preprint" ? "Organization" : "Periodical", name: p.journal },
    identifier: { "@type": "PropertyValue", propertyID: "DOI", value: p.doi },
    sameAs: `https://doi.org/${p.doi}`,
    url: `https://doi.org/${p.doi}`,
  }));
  return JSON.stringify({ "@context": "https://schema.org", "@graph": [person, ...articles] }).replace(/</g, "\\u003c");
}

// ---------- page ----------
const photo = site.photo ? picture(site.photo, site.photoAlt, { eager: true, cls: "photo", sizes: "220px" }) : null;
const nav = [["research", "Research"], ["publications", "Publications"], ["talks", "Talks"], ["cv", "CV"], ["contact", "Contact"]];
const icon = {
  sun: `<svg class="i-sun" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>`,
  moon: `<svg class="i-moon" viewBox="0 0 24 24" aria-hidden="true"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg>`,
};

const html = `<!DOCTYPE html>
<!-- Generated by scripts/render.mjs from _data/*.json. Do not edit by hand: edit the data or the script, then run "npm run render". -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(site.title)}</title>
<meta name="description" content="${esc(site.description)}">
<meta name="color-scheme" content="light dark">
<meta name="theme-color" content="#f6f4ef" media="(prefers-color-scheme: light)">
<meta name="theme-color" content="#101214" media="(prefers-color-scheme: dark)">
<link rel="canonical" href="${esc(site.url)}">
<link rel="icon" href="assets/favicon.svg" type="image/svg+xml">
<link rel="apple-touch-icon" href="assets/apple-touch-icon.png">
<meta property="og:type" content="profile">
<meta property="og:title" content="${esc(site.title)}">
<meta property="og:description" content="${esc(site.description)}">
<meta property="og:url" content="${esc(site.url)}">
<meta property="og:image" content="${esc(site.url)}assets/og.png">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta property="og:image:alt" content="${esc(site.name)} — cerebellar neuroscience">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="${esc(site.title)}">
<meta name="twitter:description" content="${esc(site.description)}">
<meta name="twitter:image" content="${esc(site.url)}assets/og.png">
<script>try{var t=localStorage.getItem("theme");if(t==="light"||t==="dark")document.documentElement.setAttribute("data-theme",t)}catch(e){}</script>
<link rel="preload" href="assets/fonts/newsreader.woff2" as="font" type="font/woff2" crossorigin>
<style>${css}</style>
<script type="application/ld+json">${jsonLd()}</script>
</head>
<body>
<a class="skip" href="#main">Skip to content</a>
<header class="site-head">
  <div class="wrap bar">
    <a class="brand" href="#top">${esc(site.name)}</a>
    <nav aria-label="Sections"><ul>${nav.map(([id, l]) => `<li><a href="#${id}">${l}</a></li>`).join("")}</ul></nav>
    <button type="button" class="theme-toggle" hidden aria-label="Switch colour theme">${icon.sun}${icon.moon}</button>
  </div>
</header>

<main id="main">
<section class="hero" id="top" aria-labelledby="name">
  <div class="wrap hero-grid">
    <div class="hero-text">
      <p class="eyebrow">Cerebellar neuroscience</p>
      <h1 id="name">${esc(site.name)}</h1>
      <p class="statement">${esc(site.statement)}</p>
      <ul class="positions">
        <li><span class="pos-label">Now</span> ${esc(site.position)}</li>
        <li><span class="pos-label">Next</span> ${site.upcomingUrl ? ext(site.upcomingUrl, site.upcoming) : esc(site.upcoming)}${site.upcomingUrl ? "" : ` ${todo("Blumberg lab URL")}`}</li>
      </ul>
      <ul class="links">
        <li>${site.email ? ext("mailto:" + site.email, "Email") : todo("email")}</li>
        ${site.links.map((l) => `<li>${ext(l.url, l.label)}</li>`).join("\n        ")}
        <li>${hasCv ? ext(site.cv, "CV (PDF)") : todo("CV PDF")}</li>
      </ul>
    </div>
    <div class="hero-photo">${photo || todoBlock("photo (portrait, ≥800 px wide; put in src/images/ and run npm run images)", "photo-ph")}</div>
  </div>
  ${traceSvg()}
</section>

<section class="section" id="research" aria-labelledby="h-research">
  <div class="wrap">
    <h2 id="h-research">Research</h2>
    <div class="themes">
${researchHtml()}
    </div>
  </div>
</section>

<section class="section" id="publications" aria-labelledby="h-pubs">
  <div class="wrap">
    <div class="toolbar">
      <div>
        <h2 id="h-pubs">Publications</h2>
        <p class="count" id="pub-count" aria-live="polite">${pubs.length} ${pubs.length === 1 ? "paper" : "papers"}</p>
      </div>
      <div class="filters" role="group" aria-label="Filter publications" hidden>
        <button type="button" data-filter="all" aria-pressed="true">All</button>
        <button type="button" data-filter="lead" aria-pressed="false">First / co-first</button>
        <button type="button" data-filter="preprint" aria-pressed="false">Preprints</button>
      </div>
    </div>
    <div class="pubs">
${publicationsHtml()}
    </div>
    <p class="source-note">List generated from <a href="https://orcid.org/0000-0002-5553-1664">ORCID</a> and PubMed, with metadata verified against Crossref.</p>
  </div>
</section>

<section class="section" id="talks" aria-labelledby="h-talks">
  <div class="wrap">
    <h2 id="h-talks">Talks &amp; posters</h2>
    ${talksHtml()}
  </div>
</section>

<section class="section" id="cv" aria-labelledby="h-cv">
  <div class="wrap">
    <h2 id="h-cv">CV</h2>
    ${hasCv ? `<p>${ext(site.cv, "Download CV (PDF)", "button")}</p>` : todoBlock(`CV PDF without home address, phone number or date of birth, saved as ${site.cv}`)}
  </div>
</section>

<section class="section" id="contact" aria-labelledby="h-contact">
  <div class="wrap">
    <h2 id="h-contact">Contact</h2>
    <p class="contact-line">${emailHtml}</p>
    <p class="muted">Department of Neuroscience, Erasmus MC, Rotterdam, the Netherlands</p>
  </div>
</section>
</main>

<footer class="site-foot">
  <div class="wrap"><p>© ${esc(site.name)} · <a href="https://github.com/sqbauer/sqbauer.github.io">Source</a></p></div>
</footer>
<script src="assets/app.js" defer></script>
</body>
</html>
`;

await writeFile(path.join(ROOT, "index.html"), html);
await writeFile(path.join(ROOT, "sitemap.xml"), `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  <url><loc>${esc(site.url)}</loc></url>
</urlset>
`);
console.log(`Rendered index.html: ${pubs.length} publications, ${talks.length} talks.`);
